// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 blk, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        vm.assume(ts > 0);
        blk = bound(blk, block.number + 1, type(uint256).max / 2);
        vm.assume(blk % 15 != 0);

        vm.roll(blk);
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");

        // Reference: no payout on non-15 blocks, so the initial 10 ether remains.
        // Mutant: always pays out the entire balance, emptying c.
        assertTrue(address(c).balance > 0);
    }
}
